mapper.update:
UPDATE sys_social_callback_event
SET process_status = 'PROCESSED',
    error_code = NULL,
    error_summary = NULL,
    claimed_by = NULL,
    claim_time = NULL
WHERE id = #{id}
  AND tenant_id = #{tenantId}
  AND process_status = 'PROCESSING'
  AND claimed_by = #{workerId}

mapper.select:
SELECT id, tenant_id, connection_id, app_config_id, event_id, event_type, event_time,
       signature_status, process_status, retry_count, next_retry_time,
       error_code, error_summary, create_time, update_time
FROM sys_social_callback_event
WHERE tenant_id = #{tenantId}

    AND connection_id = #{connectionId}


    AND event_type = #{eventType}


    AND process_status = #{processStatus}

ORDER BY id DESC
